import{_ as t,o,c as r,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Plan — FR 3.3.1: View User Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/02-profile/3-3-1-view-user-profile/plan.md","filePath":"feature/srs/02-profile/3-3-1-view-user-profile/plan.md"}'),a={name:"feature/srs/02-profile/3-3-1-view-user-profile/plan.md"};function s(c,e,i,n,l,p){return o(),r("div",null,[...e[0]||(e[0]=[d(`<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-3-1-view-user-profile" tabindex="-1">Plan — FR 3.3.1: View User Profile <a class="header-anchor" href="#plan-—-fr-3-3-1-view-user-profile" aria-label="Permalink to &quot;Plan — FR 3.3.1: View User Profile&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> — Principal-scoped personal profile retrieval (<code>GET /api/v1/users/me</code>) and profile completeness scoring (<code>GET /api/v1/users/me/completeness</code>).</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>JwtAuthFilterGatewayFilterFactory.java</code> (validates JWT and forwards principal context to <code>/api/v1/users/**</code>)</td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>controller/user/UserController.java</code> (<code>GET /api/v1/users/me</code>), <code>controller/collaborator/ProfileMatchingController.java</code> (<code>GET /api/v1/users/me/completeness</code>)</td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>service/impl/user/UserServiceImpl.java</code> (<code>getUserProfile</code>, <code>toResponse</code>), <code>service/matching/CompletenessService.java</code></td></tr><tr><td style="text-align:left;"><strong>DTOs &amp; Errors</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>UserProfileResponse</code>, <code>CompletenessService.Result</code>, <code>ErrorCode</code> (<code>UNAUTHORIZED</code>, <code>USER_NOT_FOUND</code>)</td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>model/user/User.java</code>, <code>UserRepository.java</code>, <code>UserSystemRoleRepository.java</code>, <code>WorkspaceMemberRepository.java</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/profile/index.tsx</code>, <code>src/pages/profile/components/{ProfileViewDetails,ProfilePreviewCard}.tsx</code>, <code>src/components/shared/CompletenessCard.tsx</code>, <code>src/services/userService.ts</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>src/screens/settings/AccountSettingsScreen.tsx</code>, <code>src/services/userService.ts</code></td></tr></tbody></table><h2 id="_2-api-contract-response-mapping" tabindex="-1">2. API Contract &amp; Response Mapping <a class="header-anchor" href="#_2-api-contract-response-mapping" aria-label="Permalink to &quot;2. API Contract &amp; Response Mapping&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/users/me</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;accessToken&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-&gt; 200 ApiResponse&lt;UserProfileResponse&gt;</span></span></code></pre></div><ul><li><strong>Returned Fields (<code>UserProfileResponse</code>):</strong> <code>userId</code>, <code>email</code>, <code>fullName</code>, <code>avatarUrl</code>, <code>bannerUrl</code>, <code>phone</code>, <code>role</code> (<code>SystemRole</code>, defaulting to <code>USER</code>), <code>workspaceId</code> (from token claim or fallback first active <code>WorkspaceMember</code>), <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code> (<code>List&lt;String&gt;</code> safely deserialized from JSON string; empty list on null/blank), <code>skills</code>, <code>location</code>, <code>socialLinks</code>, <code>workingLanguage</code>, <code>timezone</code>, <code>notificationPreferences</code>, <code>createdAt</code>.</li><li><strong>Principal Isolation:</strong> Identity is derived strictly from <code>@AuthenticationPrincipal AuthenticatedUser</code>; no caller-supplied <code>userId</code> parameter exists on <code>/me</code>, guaranteeing zero horizontal privilege escalation.</li></ul><h2 id="_3-postgresql-data-model" tabindex="-1">3. PostgreSQL Data Model <a class="header-anchor" href="#_3-postgresql-data-model" aria-label="Permalink to &quot;3. PostgreSQL Data Model&quot;">​</a></h2><ul><li><strong><code>users</code> table:</strong> <code>id</code> (<code>UUID</code> PK), <code>email</code> (<code>VARCHAR</code> unique), <code>full_name</code>, <code>phone</code> (<code>VARCHAR(20)</code> unique, nullable), <code>avatar_url</code>, <code>banner_url</code>, <code>professional_title</code>, <code>bio</code>, <code>portfolio_urls</code> (JSON array text), <code>working_language</code>, <code>preferences</code> (<code>JSONB</code> storing <code>timezone</code> and <code>notificationPreferences</code>), <code>created_at</code>.</li><li><strong><code>user_system_roles</code> &amp; <code>workspace_members</code>:</strong> Read-only joins/lookups to resolve global <code>SystemRole</code> and active <code>workspaceId</code> context.</li></ul><h2 id="_4-end-to-end-execution-flow" tabindex="-1">4. End-to-End Execution Flow <a class="header-anchor" href="#_4-end-to-end-execution-flow" aria-label="Permalink to &quot;4. End-to-End Execution Flow&quot;">​</a></h2><ol><li>Signed-in actor (<code>Owner, Manager, Creator, Client, Admin</code>) navigates to <code>/profile</code> (Web) or <code>AccountSettingsScreen</code> (Mobile).</li><li>Frontend calls <code>userService.getProfile()</code> (<code>GET /api/v1/users/me</code>) with TanStack Query caching keyed by authenticated <code>userId</code>.</li><li><code>UserServiceImpl.getUserProfile()</code> loads <code>User</code> by <code>currentUser.getId()</code> (<code>404 USER_NOT_FOUND</code> if absent), resolves <code>SystemRole</code> and <code>workspaceId</code>, parses <code>preferences</code> JSONB (<code>timezone</code>, <code>notificationPreferences</code>) and <code>portfolioUrls</code>, and returns <code>UserProfileResponse</code>.</li><li>UI renders <code>ProfileBannerHeader</code> + <code>ProfileViewDetails</code> (falling back to deterministic initials avatar <code>UserAvatar</code> when <code>avatarUrl</code> is empty, without mock data).</li></ol><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.3.1</code> — View User Profile</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>GET /api/v1/users/me · GET /api/v1/users/me/completeness</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>UserController, ProfileMatchingController</code> -&gt; <code>UserServiceImpl, CompletenessService</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>users</code> (<code>preferences</code> JSONB), <code>user_system_roles</code>, <code>workspace_members</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-11</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>401 UNAUTHORIZED</code>, <code>404 USER_NOT_FOUND</code></td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/profile/index.tsx</code>, <code>src/pages/profile/components/{ProfileViewDetails,ProfilePreviewCard}.tsx</code>, <code>src/components/shared/CompletenessCard.tsx</code>, <code>src/services/userService.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>src/screens/settings/AccountSettingsScreen.tsx</code>, <code>src/services/userService.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>profile.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>`,16)])])}const u=t(a,[["render",s]]);export{h as __pageData,u as default};
